<template><section class="storage-page">
 <FactoryToolbar :before-change="beforeChange" :disabled="operation.busy.value||!!operation.pending.value"><el-input v-model="filters.number" placeholder="单据编号" :disabled="!state.factoryId" @keyup.enter="search"/><el-select v-model="filters.type" placeholder="单据类型" clearable :disabled="!state.factoryId"><el-option v-for="t in typesFor(tab)" :key="t" :label="typeNames[t]" :value="t"/></el-select><el-select v-model="filters.warehouseId" placeholder="仓库" clearable :disabled="!state.factoryId"><el-option v-for="w in state.warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select><el-select v-model="filters.status" placeholder="状态" clearable :disabled="!state.factoryId"><el-option v-for="(name,value) in statusNames" :key="value" :label="name" :value="value"/></el-select><el-button class="list-action" :disabled="!state.factoryId" @click="search">查询</el-button><el-button class="list-action list-action--neutral" @click="reset">重置</el-button></FactoryToolbar>
 <OperationStatus :operation="operation"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" @click="load">重试</el-button>
 <div class="document-actions"><el-button v-if="can('metal:warehouse-order:add')" class="list-action list-action--create" :disabled="!state.factoryId||tab==='AUX'" @click="tab!=='AUX'&&editor?.open(tab)">添加</el-button><el-button v-if="can('metal:warehouse-order:export')" class="list-action" :disabled="!state.factoryId||loading" @click="exportRows">导出</el-button><el-button v-if="can('metal:material-debt:list')" :disabled="!state.factoryId" @click="debtsOpen=true">借还料账</el-button><el-button v-if="can('metal:inventory:adjust')" :disabled="!state.factoryId" @click="editor?.open('ADJUST')">库存调整</el-button></div>
 <el-tabs v-model="tab" :before-leave="beforeChange" @tab-change="reset"><el-tab-pane v-for="k in kinds" :key="k" :name="k" :label="kindNames[k]"/><el-tab-pane label="调整 / 归还 / 冲销" name="AUX"/></el-tabs>
 <el-table :data="rows" border v-loading="loading"><el-table-column prop="number" label="单据编号" min-width="220"/><el-table-column prop="orderNumber" label="生产工单" min-width="180"/><el-table-column label="工厂名称" min-width="130"><template #default="{row}">{{row.factoryName||factoryName}}</template></el-table-column><el-table-column label="仓库" min-width="150"><template #default="{row}">{{row.warehouseNames||(row.warehouseIds||[]).map(warehouseName).join('、')}}</template></el-table-column><el-table-column label="单据类型" min-width="140"><template #default="{row}">{{typeNames[row.type]||row.type}}</template></el-table-column><el-table-column prop="creatorName" label="创建人" min-width="100"/><el-table-column prop="reviewerName" label="复验人员" min-width="110"/><el-table-column label="状态" min-width="100"><template #default="{row}">{{statusNames[row.status]||row.status}}</template></el-table-column><el-table-column prop="date" :label="tab==='OUT'?'出库时间':tab==='IN'?'入库时间':tab==='RET'?'还库时间':'单据日期'" min-width="120"/><el-table-column prop="createdAt" label="创建时间" min-width="175"/><el-table-column label="操作" width="350" fixed="right"><template #default="{row}"><el-button v-if="can('metal:warehouse-order:query')" class="list-action list-action--primary list-action--row" @click="showDetail(row)">物料清单</el-button><el-button v-if="can('metal:warehouse-order:edit')" class="list-action list-action--edit list-action--row" :disabled="!mayEdit(row)" @click="editor?.open(row.kind,row)">编辑</el-button><el-button v-if="can('metal:warehouse-order:remove')" class="list-action list-action--delete list-action--row" :disabled="!['DRAFT','RETURNED','PENDING_REVIEW'].includes(row.status)" @click="cancel(row)">取消</el-button><el-button v-if="mayReview(row)" class="list-action list-action--primary list-action--row" @click="openReview(row)">复验</el-button><el-button v-if="can('metal:warehouse-order:reverse')&&row.status==='POSTED'" class="list-action list-action--edit list-action--row" @click="editor?.open('REVERSE',undefined,{reverseDocumentId:row.id,reverseDocumentNumber:row.number})">冲销</el-button></template></el-table-column></el-table>
 <div class="storage-pagination"><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[16,32,64]" :total="total" layout="total,sizes,prev,pager,next,jumper" @change="load"/></div>
 <OrderEditor ref="editor" @saved="load"/><DebtPanel v-model="debtsOpen" @repay="row=>{debtsOpen=false;editor?.open('RETURN_RIGHTS',undefined,{debt:row})}"/>
 <el-dialog v-model="detailOpen" title="物料清单" width="1100px" class="storage-dialog"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="单据编号">{{detail.number}}</el-descriptions-item><el-descriptions-item label="状态">{{statusNames[detail.status]}}</el-descriptions-item><el-descriptions-item label="生产工单">{{detail.orderNumber}}</el-descriptions-item><el-descriptions-item label="创建人">{{detail.creatorName}}</el-descriptions-item><el-descriptions-item label="原因 / 备注">{{detail.reason||'—'}}</el-descriptions-item><el-descriptions-item label="复验人员">{{detail.reviewerName}}</el-descriptions-item></el-descriptions><el-alert v-if="!['ADJUSTMENT','OWNERSHIP_RETURN','REVERSAL'].includes(detail.type)&&detail.lines.some((row:any)=>!['WEIGHT','PIECE'].includes(row.measurementMode))" title="明细计量方式缺失，请重新加载并核对配置" type="warning" :closable="false"/><el-table :data="detail.lines" border><AdjustmentColumns v-if="detail.type==='ADJUSTMENT'" :lines="detail.lines"/><template v-else><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="物料"/><el-table-column prop="netWeight" label="申报净重（g）"/><el-table-column prop="actualNetWeight" label="复验净重（g）"/><el-table-column prop="quantity" label="申报件数"/><el-table-column v-if="detail.type==='PRODUCT_IN'&&detail.lines.some((row:any)=>row.measurementMode==='WEIGHT')" prop="referenceQuantity" label="参考完工件数"/><el-table-column prop="actualQuantity" label="复验件数"/><el-table-column prop="differenceReason" label="差异原因"/><el-table-column prop="remark" label="备注"/></template></el-table></template></el-dialog>
 <ReviewDialog ref="reviewDialog" @saved="load"/>
</section></template>
<script setup lang="ts">
import AdjustmentColumns from '../storage-live/AdjustmentColumns.vue'
import ReviewDialog from '../storage-live/ReviewDialog.vue';import {computed,ref,watch,onBeforeUnmount} from 'vue';import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import request from '@/utils/request';import FactoryToolbar from '../storage-live/FactoryToolbar.vue';import OperationStatus from '../storage-live/OperationStatus.vue';import DebtPanel from '../storage-live/DebtPanel.vue';import {useStorage,useOperation,message,type Row} from '../storage-live/client';import {typeNames,statusNames,kindNames,kinds,typesFor as kindTypes,editable,clone,type Kind} from './model';import OrderEditor from './OrderEditor.vue';import {downloadCsv} from '../storage-preview/csv'
const {state,user,can,context,loadOptions}=useStorage(),route=useRoute(),router=useRouter(),base='/metal/storage-orders',tab=ref<Kind|'AUX'>('OUT'),page=ref(1),pageSize=ref(16),rows=ref<Row[]>([]),total=ref(0),loading=ref(false),error=ref(''),detailOpen=ref(false),detail=ref<Row>(),reviewDialog=ref<InstanceType<typeof ReviewDialog>>(),debtsOpen=ref(false),editor=ref<InstanceType<typeof OrderEditor>>()
const blank=()=>({number:'',type:'',warehouseId:'',status:''}),filters=ref(blank());let epoch=0,alive=true
const typesFor=(k:Kind|'AUX')=>k==='AUX'?['ADJUSTMENT','OWNERSHIP_RETURN','REVERSAL']:kindTypes(k)
const factoryName=computed(()=>state.factories.find(f=>f.id===state.factoryId)?.name||'')

const operation=useOperation(base,context,async()=>{detailOpen.value=false;window.dispatchEvent(new Event('storage-documents-changed'));ElMessage.success('操作成功');await load()})
function warehouseName(id:string){return state.warehouses.find(w=>w.id===id)?.name||id}function mayEdit(row:Row){return (row.canEdit??editable(row))&&String(row.creatorId)===String(user.id)&&row.type!=='CUSTOMER_IN'}function mayReview(row:Row){return row.canReview??(row.status==='PENDING_REVIEW'&&String(row.reviewerId)===String(user.id)&&(can('metal:warehouse-order:receive')||can('metal:warehouse-order:accept')))}
async function load(){const current=context(),id=++epoch;if(!state.factoryId){rows.value=[];total.value=0;return}loading.value=true;error.value='';try{const r:any=await request({url:base+'/list',params:{factoryId:state.factoryId,kind:tab.value,...filters.value,pageNum:page.value,pageSize:pageSize.value},quiet:true});if(current===context()&&id===epoch&&alive){rows.value=r.rows||[];total.value=r.total||0}}catch(e){if(current===context()&&id===epoch)error.value=message(e)}finally{if(id===epoch)loading.value=false}}
function search(){page.value=1;void load()}function reset(){filters.value=blank();page.value=1;void load()}
async function read(id:string){const current=context(),r:any=await request({url:base+'/'+id,params:{factoryId:state.factoryId}});return current===context()?r.data:null}
async function showDetail(row:Row){try{const data=await read(row.id);if(data){detail.value=data;detailOpen.value=true}}catch(e){error.value=message(e)}}
async function openReview(row:Row){if(operation.pending.value||operation.busy.value)return;await reviewDialog.value?.open(row.id)}
async function cancel(row:Row){const current=context();try{const answer=await ElMessageBox.prompt('请输入取消原因，已经过账的单据须使用冲销。','取消单据',{inputValidator:v=>!!v?.trim()||'请输入原因'});if(current===context())await operation.send(`${base}/${row.id}/cancel`,{factoryId:state.factoryId,version:row.version,reason:answer.value})}catch{}}
async function exportRows(){const current=context(),all:Row[]=[];try{const r:any=await request({url:'/metal/storage-orders/export',params:{factoryId:state.factoryId,kind:tab.value,...filters.value}});if(current!==context())return;all.push(...r.data);downloadCsv('仓储单据',['单据编号','生产工单','工厂','类型','创建人','复验人员','状态','日期','创建时间'],all.map(r=>[r.number,r.orderNumber,factoryName.value,typeNames[r.type],r.creatorName,r.reviewerName,statusNames[r.status],r.date,r.createdAt]))}catch(e){error.value=message(e)}}
async function beforeChange(){if(operation.pending.value||operation.busy.value)return false;if(editor.value&&!await editor.value.requestClose())return false;return await reviewDialog.value?.requestClose()??true}
async function routeReview(){const id=route.query.review;if(typeof id!=='string'||!state.factoryId)return;if(await beforeChange()){await openReview({id,factoryId:state.factoryId});const query={...route.query};delete query.review;void router.replace({query})}}
watch(()=>state.factoryId,()=>{epoch++;detailOpen.value=false;reset();void loadOptions();void routeReview()},{immediate:true});watch(()=>route.query.review,routeReview);watch(()=>[route.query.detail,state.factoryId],async()=>{const id=route.query.detail;if(typeof id==='string'&&state.factoryId){await showDetail({id,factoryId:state.factoryId});const query={...route.query};delete query.detail;void router.replace({query})}},{immediate:true});onBeforeRouteLeave(beforeChange);onBeforeUnmount(()=>{alive=false;epoch++})
</script><style scoped>.document-actions{display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap}.document-actions .el-button{margin:0}</style>

<style scoped>.review-lines :deep(.no-review-sources .el-table__expand-icon){display:none}</style>
